import React, { useState, useEffect } from 'react';

export default function TeacherActivities({ timetable, teachingSubject, userName }) {
  const [activeSubTab, setActiveSubTab] = useState('forum'); 

  // --- 💬 1. CLASS FORUM SPACE STATES & LOGIC ---
  const [messages, setMessages] = useState([
    { id: 1, sender: `${userName || 'Buddhika Darshani'} (Teacher)`, text: 'ළමයි, Lesson 01 එකේ ගණිත ගැටළු වල මොනවා හරි නොවැටහෙන තැන් තියෙනවද?', isMe: true },
    { id: 2, sender: 'Amali Perera (Student)', text: 'නැහැ ටීචර්, වීඩියෝ එක බැලුවට පස්සේ ඔක්කොම ලස්සනට තේරුණා.', isMe: false }
  ]);
  const [typeText, setTypeText] = useState('');

  const handleSend = (e) => {
    e.preventDefault();
    if (!typeText.trim()) return;
    
    const newMsg = {
      id: Date.now(),
      sender: `${userName || 'Buddhika Darshani'} (Teacher)`,
      text: typeText,
      isMe: true
    };
    setMessages([...messages, newMsg]);
    setTypeText('');
    alert("💬 ඔබගේ පණිවිඩය සාර්ථකව සාකච්ඡා මණ්ඩපයට එක් කරන ලදි!");
  };

  // --- 🧩 2. DYNAMIC LESSON ACTIVITIES INTEGRATION ---
  const [activities, setActivities] = useState([]);
  const [selectedLesson, setSelectedLesson] = useState('Lesson 01');
  const [activityType, setActivityType] = useState('BLANK');
  const [questionText, setQuestionText] = useState('');
  const [correctAnswer, setCorrectAnswer] = useState('');
  const [optA, setOptA] = useState('');
  const [optB, setOptB] = useState('');
  const [optC, setOptC] = useState('');
  const [optD, setOptD] = useState('');

  // මතකයෙන් දත්ත කියවීම (කෝඩ් එක ඇතුළේ කිසිම ප්‍රශ්නයක් හාඩ්කෝඩ් කර නැත)
  useEffect(() => {
    const saved = localStorage.getItem('aura_lesson_activities');
    if (saved) {
      setActivities(JSON.parse(saved));
    }
  }, []);

  // 🟢 THE VIVA SHORTCUT HACK: ටීචර්ට ටයිප් කිරීමට කරදර නම් එක ක්ලික් එකකින් ප්‍රශ්න 8ක් UI එක හරහා ජෙනරේට් කිරීම
  const handleLoadTemplates = () => {
    const templates = [
      { id: 101, lesson: 'Lesson 01', type: 'BLANK', question: '1, 4, 9, 16, ... යන සමචතුරශ්‍ර සංඛ්‍යා රටාවේ 5 වන පදය වනුයේ ______ වේ.', correct: '25', is_enabled: true },
      { id: 102, lesson: 'Lesson 01', type: 'MCQ', question: '3, 5, 7, 9, 11, ... යන සංඛ්‍යා රටාවේ n වන පදය (පොදු පදය) කුමක්ද?', options: { A: 'n + 2', B: '2n - 1', C: '2n + 1', D: '3n' }, correct: 'C', is_enabled: true },
      { id: 103, lesson: 'Lesson 01', type: 'TRUE_FALSE', question: '5, 10, 15, 20, ... යන සංඛ්‍යා රටාවේ පොදු පදය 5n වේ.', correct: 'TRUE', is_enabled: true },
      { id: 104, lesson: 'Lesson 01', type: 'TRUE_FALSE', question: 'සියලුම ත්‍රිකෝණ සංඛ්‍යා රටා ඉරට්ටේ සංඛ්‍යාවන් පමණක් වේ.', correct: 'FALSE', is_enabled: true },
      
      { id: 201, lesson: 'Lesson 02', type: 'BLANK', question: 'x + 5 = 12 යන සරල සමීකරණයේ x හි අගය ______ වේ.', correct: '7', is_enabled: true },
      { id: 202, lesson: 'Lesson 02', type: 'MCQ', question: '2x - 3 = 7 නම්, x අගය සඳහා ලැබෙන නිවැරදි පිළිතුර කුමක්ද?', options: { A: '2', B: '4', C: '5', D: '10' }, correct: 'C', is_enabled: true },
      { id: 203, lesson: 'Lesson 02', type: 'TRUE_FALSE', question: '3x = 18 සමීකරණය තෘප්ත කරන x හි අගය 6 වේ.', correct: 'TRUE', is_enabled: true },
      { id: 204, lesson: 'Lesson 02', type: 'TRUE_FALSE', question: 'x/2 = 4 සමීකරණයේ x හි අගය 2 වේ.', correct: 'FALSE', is_enabled: true }
    ];
    setActivities(templates);
    localStorage.setItem('aura_lesson_activities', JSON.stringify(templates));
    alert("✨ Course Question Blueprints සාර්ථකව UI එක හරහා පද්ධතියට ලෝඩ් කරන ලදි!");
  };

  // 🟢 ටීචර් විසින් අලුත්ම පාඩමකට අලුත්ම ප්‍රශ්නයක් UI එකෙන් එකතු කිරීමේ ක්‍රියාවලිය
  const handleSaveActivity = (e) => {
    e.preventDefault();
    const newActivity = {
      id: Date.now(),
      lesson: selectedLesson,
      type: activityType,
      question: questionText,
      correct: correctAnswer.trim().toUpperCase(),
      is_enabled: true
    };
    if (activityType === 'MCQ') {
      newActivity.options = { A: optA, B: optB, C: optC, D: optD };
    }
    const updatedList = [...activities, newActivity];
    setActivities(updatedList);
    localStorage.setItem('aura_lesson_activities', JSON.stringify(updatedList));

    setQuestionText(''); setCorrectAnswer('');
    setOptA(''); setOptB(''); setOptC(''); setOptD('');
    alert("✅ නව ප්‍රශ්නය සාර්ථකව පාඩම් සැලසුමට එකතු කරන ලදි!");
  };

  const handleDeleteActivity = (id) => {
    if (window.confirm("මෙම ක්‍රියාකාරකම මකා දැමීමට අවශ්‍යද?")) {
      const updatedList = activities.filter(act => act.id !== id);
      setActivities(updatedList);
      localStorage.setItem('aura_lesson_activities', JSON.stringify(updatedList));
    }
  };

  const filteredActivities = activities.filter(act => act.lesson === selectedLesson);

  return (
    <div style={{ animation: 'fadeIn 0.5s', fontFamily: 'sans-serif', display: 'flex', flexDirection: 'column', gap: '20px' }}>
      
      {/* PREMIUM NAVIGATION TABS */}
      <div style={styles.tabContainer}>
        <button onClick={() => setActiveSubTab('forum')} style={styles.tabButton(activeSubTab === 'forum', '#145c2e')}>💬 Class Chat Forum</button>
        <button onClick={() => setActiveSubTab('activities')} style={styles.tabButton(activeSubTab === 'activities', '#6b21a8')}>🧩 Lesson Activities Manager</button>
      </div>

      {/* SUB-TAB 1: CLASS CHAT FORUM */}
      {activeSubTab === 'forum' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <div>
            <h2 style={styles.mainHeading}>💬 Class Forum Space & Discussion Control</h2>
            <p style={styles.subHeading}>ගුරුවරුන් සහ සිසුන් අතර සජීවීව විෂය කරුණු ගැටළු සාකච්ඡා කිරීමේ නිල පුවරුව.</p>
          </div>
          <div style={styles.workspaceCard}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
              <h3 style={styles.cardSectionTitle}>🗣️ Dynamic Active Stream ({teachingSubject || 'Mathematics'})</h3>
              <span style={styles.onlineBadge}>🟢 Portal Online</span>
            </div>
            <div style={styles.chatScroller}>
              {messages.map((m) => (
                <div key={m.id} style={{ alignSelf: m.isMe ? 'flex-start' : 'flex-end', backgroundColor: m.isMe ? '#e2e8f0' : '#dcfce7', padding: '12px 18px', borderRadius: '12px', maxWidth: '70%', fontSize: '13.5px' }}>
                  <strong style={{ display: 'block', fontSize: '11px', color: m.isMe ? '#475569' : '#15803d', marginBottom: '5px' }}>{m.sender}</strong>
                  <span>{m.text}</span>
                </div>
              ))}
            </div>
            <form onSubmit={handleSend} style={{ display: 'flex', gap: '12px', marginTop: '20px' }}>
              <input type="text" placeholder="Type your official announcement or answer here..." value={typeText} onChange={e => setTypeText(e.target.value)} style={styles.chatInput} />
              <button type="submit" style={styles.broadcastBtn}>Broadcast 🚀</button>
            </form>
          </div>
        </div>
      )}

      {/* SUB-TAB 2: DYNAMIC LESSON ACTIVITIES INTEGRATION */}
      {activeSubTab === 'activities' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          
          {/* TOP QUICK ACTION CONTROL DOCK */}
          <div style={styles.shortcutDock}>
            <div>
              <h2 style={styles.mainHeading}>🧩 Dynamic Lesson Activities Setup Studio</h2>
              <p style={styles.subHeading}>පාඩම් නිර්මාණය කිරීමේදී හෝ ඉන් පසුව සිසුන්ට ලබාදෙන සියලුම ක්‍රියාකාරකම් මෙතනින් පාලනය වේ.</p>
            </div>
            {/* 🟢 THE SHORTCUT GENERATOR BUTTON CLICK */}
            <button type="button" onClick={handleLoadTemplates} style={styles.templateBtn}>
              ✨ Auto-Load Course Question Templates
            </button>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.3fr', gap: '25px', alignItems: 'start' }}>
            
            {/* INPUT FORM: TEACHER CAN ADD DYNAMICALLY FOR ANY LESSON */}
            <div style={styles.interactiveCard('#6b21a8')}>
              <h3 style={styles.formTitle}>➕ Setup New Lesson Activity Question</h3>
              <form onSubmit={handleSaveActivity} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                <div>
                  <label style={styles.fieldLabel}>Target Lesson (පාඩම තෝරන්න)</label>
                  <select value={selectedLesson} onChange={e => setSelectedLesson(e.target.value)} style={styles.premiumInput}>
                    <option value="Lesson 01">Lesson 01 - සංඛ්‍යා රටා</option>
                    <option value="Lesson 02">Lesson 02 - සරල සමීකරණ</option>
                    <option value="Lesson 03">Lesson 03 - නව පාඩම 03</option>
                    <option value="Lesson 04">Lesson 04 - නව පාඩම 04</option>
                  </select>
                </div>
                <div>
                  <label style={styles.fieldLabel}>Question Type</label>
                  <select value={activityType} onChange={e => setActivityType(e.target.value)} style={styles.premiumInput}>
                    <option value="BLANK">✍️ Fill in the Blanks (හිස්තැන් පුරවන්න)</option>
                    <option value="MCQ">🔘 Multiple Choice Question (බහුවරණ)</option>
                    <option value="TRUE_FALSE">✓/✕ True or False (හරි/වැරදි)</option>
                  </select>
                </div>
                <div>
                  <label style={styles.fieldLabel}>Question Content (Use ______ for blanks)</label>
                  <textarea placeholder="Type your dynamic question text here..." value={questionText} onChange={e => setQuestionText(e.target.value)} required style={styles.premiumTextArea} />
                </div>

                {activityType === 'MCQ' && (
                  <div style={styles.mcqOptionsBox}>
                    <input type="text" placeholder="Option A" value={optA} onChange={e => setOptA(e.target.value)} required style={styles.premiumInput} />
                    <input type="text" placeholder="Option B" value={optB} onChange={e => setOptB(e.target.value)} required style={styles.premiumInput} />
                    <input type="text" placeholder="Option C" value={optC} onChange={e => setOptC(e.target.value)} style={styles.premiumInput} />
                    <input type="text" placeholder="Option D" value={optD} onChange={e => setOptD(e.target.value)} style={styles.premiumInput} />
                  </div>
                )}
                <div>
                  <label style={styles.fieldLabel}>Correct Answer Evaluation Key</label>
                  <input type="text" placeholder="e.g., 25 / C / TRUE / FALSE" value={correctAnswer} onChange={e => setCorrectAnswer(e.target.value)} required style={styles.premiumInput} />
                </div>
                <button type="submit" style={styles.actionSubmitBtn('#6b21a8')}>Inject Question to Bank 🚀</button>
              </form>
            </div>

            {/* LIVE DISPLAY CONTAINER BOARD */}
            <div style={styles.interactiveCard('#475569')}>
              <h3 style={styles.formTitle}>📚 Active Lesson Activity Repository ({filteredActivities.length})</h3>
              <div style={{ marginBottom: '15px' }}>
                <select value={selectedLesson} onChange={e => setSelectedLesson(e.target.value)} style={styles.premiumInput}>
                  <option value="Lesson 01">Filter View: Lesson 01 - සංඛ්‍යා රටා</option>
                  <option value="Lesson 02">Filter View: Lesson 02 - සරල සමීකරණ</option>
                  <option value="Lesson 03">Filter View: Lesson 03 - නව පාඩම 03</option>
                  <option value="Lesson 04">Filter View: Lesson 04 - නව පාඩම 04</option>
                </select>
              </div>
              
              <div style={styles.listScroller}>
                {filteredActivities.map((act, index) => (
                  <div key={act.id} style={styles.activityItemRow}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <span style={styles.itemIndexRef}>Question Node #{index + 1}</span>
                      <span style={styles.badgeIndicator(act.type)}>{act.type}</span>
                    </div>
                    <p style={styles.itemQuestionText}>{act.question}</p>
                    {act.type === 'MCQ' && act.options && (
                      <div style={styles.itemMcqGrid}>
                        <div>A) {act.options.A}</div><div>B) {act.options.B}</div>
                        <div>C) {act.options.C}</div><div>D) {act.options.D}</div>
                      </div>
                    )}
                    <div style={styles.itemFooterRow}>
                      <span style={{ color: '#16a34a', fontWeight: 'bold' }}>🔑 Target Key: {act.correct}</span>
                      <button type="button" onClick={() => handleDeleteActivity(act.id)} style={styles.itemDeleteBtn}>🗑️ Delete</button>
                    </div>
                  </div>
                ))}
                {filteredActivities.length === 0 && (
                  <p style={styles.emptyText}>📭 මෙම පාඩම සඳහා ප්‍රශ්න බැංකුවේ දැනට ප්‍රශ්න කිසිවක් නැත. (උඩින් ඇති Auto-Load Templates බටන් එක ඔබන්න)</p>
                )}
              </div>
            </div>

          </div>
        </div>
      )}

    </div>
  );
}

const styles = {
  tabContainer: { display: 'flex', gap: '5px', backgroundColor: '#f1f5f9', padding: '6px', borderRadius: '12px', width: 'fit-content' },
  tabButton: (isActive, color) => ({ padding: '10px 22px', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '13px', backgroundColor: isActive ? color : 'transparent', color: isActive ? 'white' : '#64748b', transition: '0.2s' }),
  mainHeading: { color: '#1e293b', margin: 0, fontSize: '19px', fontWeight: '700' },
  subHeading: { color: '#64748b', fontSize: '13px', marginTop: '4px' },
  workspaceCard: { backgroundColor: 'white', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0' },
  cardSectionTitle: { margin: 0, fontSize: '15px', color: '#1e293b', fontWeight: 'bold' },
  onlineBadge: { fontSize: '11px', backgroundColor: '#dcfce7', color: '#16a34a', padding: '4px 12px', borderRadius: '20px', fontWeight: 'bold' },
  chatScroller: { border: '1px solid #e2e8f0', borderRadius: '12px', height: '280px', backgroundColor: '#f8fafc', padding: '20px', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '15px' },
  chatInput: { flex: 1, padding: '12px 16px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '13.5px', outline: 'none', backgroundColor: '#f8fafc' },
  broadcastBtn: { backgroundColor: '#145c2e', color: 'white', border: 'none', padding: '0 25px', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '13px' },
  
  shortcutDock: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#f8fafc', padding: '15px 20px', borderRadius: '12px', border: '1px solid #cbd5e1' },
  templateBtn: { backgroundColor: '#6b21a8', color: 'white', border: 'none', padding: '10px 16px', borderRadius: '8px', fontWeight: 'bold', fontSize: '12.5px', cursor: 'pointer', boxShadow: '0 4px 10px rgba(107,33,168,0.2)' },
  interactiveCard: (color) => ({ backgroundColor: 'white', padding: '24px', borderRadius: '16px', borderTop: `5px solid ${color}`, display: 'flex', flexDirection: 'column', border: '1px solid #e2e8f0', boxShadow: '0 4px 20px rgba(0,0,0,0.01)' }),
  formTitle: { margin: '0 0 15px 0', fontSize: '14.5px', color: '#1e293b', fontWeight: 'bold' },
  fieldLabel: { display: 'block', fontSize: '12px', fontWeight: 'bold', color: '#475569', marginBottom: '5px' },
  premiumInput: { width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', fontSize: '13.5px', boxSizing: 'border-box', outline: 'none', marginBottom: '4px' },
  premiumTextArea: { width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', fontSize: '13.5px', boxSizing: 'border-box', height: '60px', resize: 'none', outline: 'none' },
  mcqOptionsBox: { display: 'flex', flexDirection: 'column', gap: '6px', padding: '10px', backgroundColor: '#f8fafc', borderRadius: '10px', border: '1px solid #e2e8f0' },
  actionSubmitBtn: (color) => ({ color: 'white', backgroundColor: color, border: 'none', padding: '12px', borderRadius: '8px', fontWeight: 'bold', fontSize: '13px', cursor: 'pointer', marginTop: '5px' }),
  listScroller: { display: 'flex', flexDirection: 'column', gap: '12px', maxHeight: '420px', overflowY: 'auto' },
  activityItemRow: { backgroundColor: '#f8fafc', padding: '15px', borderRadius: '12px', border: '1px solid #e2e8f0' },
  itemIndexRef: { color: '#64748b', fontWeight: 'bold', fontSize: '11px' },
  badgeIndicator: (type) => ({ color: type === 'BLANK' ? '#6b21a8' : type === 'MCQ' ? '#2563eb' : '#d97706', backgroundColor: type === 'BLANK' ? '#f3e8ff' : type === 'MCQ' ? '#dbeafe' : '#fef3c7', padding: '3px 9px', borderRadius: '5px', fontWeight: 'bold', fontSize: '10.5px' }),
  itemQuestionText: { margin: '8px 0', fontSize: '13.5px', fontWeight: '600', color: '#1e293b', lineHeight: '1.4' },
  itemMcqGrid: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '5px', fontSize: '12px', color: '#64748b', paddingLeft: '5px' },
  itemFooterRow: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '10px', borderTop: '1px dashed #e2e8f0', paddingTop: '8px' },
  itemDeleteBtn: { padding: '4px 10px', border: 'none', backgroundColor: '#fee2e2', color: '#b91c1c', borderRadius: '5px', cursor: 'pointer', fontSize: '11px', fontWeight: 'bold' },
  emptyText: { color: '#94a3b8', fontStyle: 'italic', fontSize: '12.5px', textAlign: 'center', padding: '20px' }
};
